class Solution {
    public int lengthOfLongestSubsequence(int[] nums, int target) {
        int[] dp = new int[target + 1];
        Arrays.fill(dp, -1);
        dp[0] = 0;
        for (int num : nums)
            for (int s = target; s >= num; s--)
                if (dp[s - num] != -1)
                    dp[s] = Math.max(dp[s], dp[s - num] + 1);
        return dp[target];
    }
}

